head.script:
scwin.screenId = "jldfil05500";

///////// 1. 변수 및 선언 영역 /////////

scwin.default_props = "toolbar=no,location=no,status=no,menubar=no,scrollbars=yes,resizable=no,";


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_when_27", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "entity.code"); })() !== (dma_irCalcList.get("month") ?? (() => { throw new Error("unresolved:" + "irCalcList.month"); })())); } }, { id: "c_otherwise_30", fn: function(){ return (!(((() => { throw new Error("unresolved:data:" + "entity.code"); })() !== (dma_irCalcList.get("month") ?? (() => { throw new Error("unresolved:" + "irCalcList.month"); })())))); } }, { id: "c_when_73_txt", fn: function(){ return ((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())==0 || (dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())%7==0 || (() => { throw new Error("unresolved:data:" + "entity.holidayYN"); })()==='Y'); } }, { id: "c_when_74_txt", fn: function(){ return ((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())%7==6); } }, { id: "c_otherwise_75", fn: function(){ return (!(((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())==0 || (dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())%7==0 || (() => { throw new Error("unresolved:data:" + "entity.holidayYN"); })()==='Y') || ((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())%7==6))); } }, { id: "c_when_85_txt", fn: function(){ return ((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())%7==6); } }, { id: "c_otherwise_86", fn: function(){ return (!(((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())%7==6))); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_25", entity: "dlt_monthArray", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return String(v("name")) + "월"; } }, { childId: "__rc1", fn: function (v, i) { return String(v("name")) + "월"; } }] },
        { genId: "c_foreach_70", entity: "dlt_irCalcListDateList", countIds: [], cells: [{ childId: "__rc2", fn: function (v, i) { return String(v("day")); } }] },
        { genId: "c_foreach_91", entity: "dlt_entityIrList", countIds: [], cells: [{ childId: "btn_SearchIRDetail", fn: function (v, i) { return String(v("comNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getTotalRow();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: entry_edge). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil05500.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.slc_selectYear_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_selectYear_onchange = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_selectYear_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.iRCalc();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05500.slc_selectYear_onchange' }); }
};

/**
 * @event
 * @name scwin.btn_IRCalcMonth_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_IRCalcMonth_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_IRCalcMonth_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.iRCalcMonth((String(((() => { throw new Error("unresolved:data:" + "entity.code"); })()) == null ? '' : ((() => { throw new Error("unresolved:data:" + "entity.code"); })())).indexOf('$' + '{') >= 0 ? '' : String(((() => { throw new Error("unresolved:data:" + "entity.code"); })()) == null ? '' : ((() => { throw new Error("unresolved:data:" + "entity.code"); })()))))
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05500.btn_IRCalcMonth_onclick' }); }
};

/**
 * @method
 * @name scwin.btn_SearchIRDetail_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_SearchIRDetail_onclick = async function(e){
    const ev = e;
    const event = ev;
    const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
    /* sdd-asis-lifecycle:begin btn_SearchIRDetail_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await scwin.searchIRDetail('' + dlt_entityIrList.getCellData(0, "irSeq") + '')
    /* sdd-asis-lifecycle:end */
};

/**
 * @event
 * @name scwin.__ev_4_btn_SearchIRDetail_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.__ev_4_btn_SearchIRDetail_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin __ev_4_btn_SearchIRDetail_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.searchIRDetail('' + dlt_entityIrList.getCellData(0, "irSeq") + '')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05500.__ev_4_btn_SearchIRDetail_onclick' }); }
};

/**
 * @event
 * @name scwin.img_101_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_101_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_101_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.goURL('registerIR')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05500.img_101_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_IRCalc
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_IRCalc = async function () {
    const sbmOptions = {
        id: "tx_fn_IRCalc",
        method: "post",
        action: "/list/supportIR.do",
        ref: "dma_IRCalcReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil05500.tx_fn_IRCalc" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

