/**
 * @method
 * @name scwin.tx_load_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/list/supportIR.do?method=searchIR",
        ref: "dma_loadListReq",
        target: "dlt_entityIrList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil05500.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.iRCalc
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.iRCalc = async function () {
    /* sdd-asis-lifecycle:begin fn_IRCalc — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_IRCalcReq').set('method', 'searchIR');
    (document.SupportIRForm || { elements: [] }).target = "_self";
    await scwin.tx_fn_IRCalc();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.iRCalcMonth
 * @author Inswave
 * @date 2026. 09. 29
 * @param month
 * @returns
 * @hidden N
*/
scwin.iRCalcMonth = async function (month) {
    /* sdd-asis-lifecycle:begin fn_IRCalcMonth — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_IRCalcReq').set('selectMonth', month);
    await scwin.iRCalc();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goURL
 * @author Inswave
 * @date 2026. 09. 29
 * @param method
 * @returns
 * @hidden N
*/
scwin.goURL = async function (method) {
    /* sdd-asis-lifecycle:begin fn_GoURL — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (method === 'registerIR') {
        $c.util.getComponent('dma_IRCalcReq').set('method', method);
        (document.SupportIRForm || { elements: [] }).target = "_self";
        await scwin.tx_fn_GoURL();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchIRDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param ir_seq
 * @returns
 * @hidden N
*/
scwin.searchIRDetail = async function (ir_seq) {
    /* sdd-asis-lifecycle:begin fn_SearchIRDetail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const props = scwin.default_props + "width=567,height=302";
    (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "about:blank", unresolved: "nav:" + "about:blank" }; })();
    $c.util.getComponent('dma_IRCalcReq').set('method', "searchIRDetail");
    $c.util.getComponent('dma_IRCalcReq').set('irSeq', ir_seq);
    (document.SupportIRForm || { elements: [] }).target = "detail_pop";
    await scwin.tx_fn_SearchIRDetail();
    /* sdd-asis-lifecycle:end */
};
